// ScreenCam signal glitch, CC0-1.0.
// Horizontal lost-sync bands and RGB channel separation.
uniform float intensity; // = 0.5
float signalHash(vec2 position) {
    vec3 p = fract(vec3(position.x, position.y, position.x) * vec3(0.1031, 0.1030, 0.0973));
    p += dot(p, p.yzx + 33.33);
    return fract((p.x + p.y) * p.z);
}
vec4 transition(vec2 uv) {
    float amount = intensity * sin(3.141592653589793 * progress);
    float line = floor(uv.y * min(900.0, resolution.y));
    float tick = floor(progress * 48.0);
    float band = uv.y * 27.0 + tick * 0.13;
    float block = floor(band);
    float coarse = mix(signalHash(vec2(block, tick) + seedVector),
                       signalHash(vec2(block + 1.0, tick) + seedVector),
                       smoothstep(0.0, 1.0, fract(band)));
    float fine = signalHash(vec2(line + 31.0, tick + 17.0) + seedVector.yx);
    float dropout = signalHash(vec2(line + 73.0, tick + 3.0) + seedVector);
    float wave = sin(uv.y * 19.0 + tick * 0.37 + seedVector.x) * 0.018;
    float longTear = step(0.94, dropout) * (fine * 2.0 - 1.0) * 0.10;
    float shift = ((coarse * 2.0 - 1.0) * 0.11 + wave
                   + (fine * 2.0 - 1.0) * 0.035 + longTear) * amount;
    float split = (0.003 + 0.012 * fine + 0.003 * coarse) * amount;
    vec2 center = uv + vec2(shift, 0.0);
    vec2 redPoint = center + vec2(split, 0.0);
    vec2 bluePoint = center - vec2(split * 0.85, 0.0);
    float gate = smoothstep(0.30, 0.70, progress + (coarse - 0.5) * 0.48);
    float blend = mix(progress, gate, amount);
    vec4 red = mix(getFromColor(redPoint), getToColor(redPoint), blend);
    vec4 green = mix(getFromColor(center), getToColor(center), blend);
    vec4 blue = mix(getFromColor(bluePoint), getToColor(bluePoint), blend);
    float alpha = max(red.a, max(green.a, blue.a));
    vec3 rgb = vec3(red.r, green.g, blue.b);
    float lineGain = 1.0 - amount * (0.10 * fine + 0.32 * step(0.975, dropout));
    return vec4(rgb * lineGain, alpha);
}
